Contract ManageCashierCRUDService::createCashier(id:Integer,name:String): Boolean {
          definition:
          cashier:Cashier = Store.allInstance()->any(s | s.Cashiers->includes(cashier))->Cashiers->any(c | c.Id = id)

            precondition:
          id > 0 and name <> null and name <> '' and Store.allInstance()->exists(s | s.Cashiers->excludes(cashier))

            postcondition:
          let newCashier:Cashier in newCashier.Id = id and newCashier.Name = name and Store.allInstance()->any(s | s.Cashiers->includes(newCashier))

        }

Contract ManageSupplierCRUDService::createSupplier(id:Integer,name:String): Boolean {

            precondition:
          id > 0 and name <> null and name <> '' and Supplier.allInstance()->excludes(s:Supplier | s.Id = id)

            postcondition:
          let s:Supplier in s.oclIsNew(), Supplier.allInstance()->includes(s), s.Id = id, s.Name = name, result = true

        }

