Contract ManageLibrarianCRUDService::createLibrarian(librarianid:String,name:String,password:String): Boolean {

            precondition:
          librarianid.oclIsTypeOf(String) and name.oclIsTypeOf(String) and password.oclIsTypeOf(String) and Librarian.allInstance()->excludes(Librarian.allInstance()->any(l:Librarian|l.LibrarianID=librarianid))

            postcondition:
          Librarian.allInstance()->includes(newLibrarian) and newLibrarian.LibrarianID = librarianid and newLibrarian.Name = name and newLibrarian.Password = password and result = true

        }

Contract ManageSubjectCRUDService::createSubject(name:String): Boolean {

            precondition:
          name.oclIsUndefined() = false and name.size() > 0 and Subject.allInstance()->excludes(Subject.allInstance()->any(s | s.Name = name))

            postcondition:
          Subject.allInstance()->includes(Subject.allInstance()->any(s | s.Name = name)) and result = true

        }

Contract LibraryManagementSystemSystem::recommendBook(uid:String,callNo:String,title:String,edition:String,author:String,publisher:String,description:String,isbn:String): Boolean {
          definition:
          user:User = User.allInstance()->any(u | u.UserID = uid), book:Book = Book.allInstance()->any(b | b.CallNo = callNo)

            precondition:
          user.oclIsUndefined() = false and book.oclIsUndefined() = false and user.BorrowStatus = BorrowStatus.NORMAL and user.LoanedNumber < 10

            postcondition:
          let newRec:RecommendBook in newRec.oclIsNew(), newRec.RecommendDate = self.currentDate, newRec.RecommendUser = user, user.RecommendedBook->includes(newRec), Book.allInstance()->includes(book)

        }

Contract SearchBook::searchBookByBarCode(barcode:String): Set(Book) {

            precondition:
          barcode.oclIsUndefined() = false and BookCopy.allInstance()->exists(bc | bc.Barcode = barcode and bc.Status = 'AVAILABLE')

            postcondition:
          result = BookCopy.allInstance()->select(bc | bc.Barcode = barcode)->collect(bc | bc.BookBelongs)

        }

